let today = new Date();

// pega o campo lastfollowup
let lastfollowup = $input.first().json.last_followup;

if(!lastfollowup){
  return [
    {
      json: { passedTwoDays: true }
    }
  ]
}


let lastFollowupDate = new Date(lastfollowup)

// Cria limite de 2 dias a partir do followup
let limitDate = new Date(lastfollowup)
limitDate.setDate(lastFollowupDate.getDate() + 2);

let passedTwoDays = today > limitDate; // true quando passou de 2 dias

return [
  {
    json: { passedTwoDays }
  }
]
